// SPDX-License-Identifier: AGPL-3.0-or-later
// Room: First-floor stair hall. Inner air x5..8 y14..17 z7..21. Flight 1 arrives at x7..8 z16 and flight 2 rises
// from x5..6 z15, so the arrival lane (x7..8 z16..21, out to the dining door x9 z18 and the wing door x7 z22) stays
// clear. Furniture sits on the west side: a settle (spruce stairs facing east, backs on the wall) with a fence-and-
// slab table in front of it, and a barrel store at the south-west corner. Hanging lanterns from the second floor's
// underside light the hall, the north part included.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { hangLantern } from "../vocab.mjs";

export function build(g) {
  // y14: settle seats (x5, z17..19), table base (x6 z18), barrels (x5 z20, x5..6 z21). Rows run along +x (x5..8),
  // successive rows along +z (z16..21).
  layers(g, [5, 14, 16], {
    "S": ["spruce_stairs", { facing: "east", half: "bottom", shape: "straight" }],
    "F": "spruce_fence",
    "B": "barrel",
  }, [
    ["    ", "S   ", "SF  ", "S   ", "B   ", "BB  "],
  ]);

  // y15: the table top, a bottom spruce slab on the fence.
  layers(g, [5, 15, 16], { "T": ["spruce_slab", { type: "bottom" }] }, [
    ["    ", "    ", " T  ", "    ", "    ", "    "],
  ]);

  // Lanterns hang from the second floor's underside (floor y18 is solid over these cells).
  hangLantern(g, 6, 17, 9);
  hangLantern(g, 8, 17, 13);
  hangLantern(g, 6, 17, 17);
  hangLantern(g, 6, 17, 20);
}
// SPDX-License-Identifier: AGPL-3.0-or-later
// Room: Second-floor hall (top landing, inner air x5..8 y19..22 z7..16). The stair well (x5..6 z12..16) and its
// rail at x7 are built by the stair joiner; the landing stays a clear lane from the stair arrival (z11) to the
// corridor door (x9 z13) and the bath door (x7 z17). Focal piece: a bookshelf wall in the north-east corner, with
// a barrel stack in front of it. Two hanging lanterns light the landing.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  // floor layer y19 (x5..8 across, z7..16 down); ' ' is left as it is
  const floor = {
    B: "bookshelf",
    b: "barrel",
    c: "red_carpet",
  };
  layers(g, [5, 19, 7], floor, [
    "BB  ", // z7
    "b  B", // z8
    "  cB", // z9
    " ccB", // z10
    "    ", // z11 stair arrival: x5..6 kept clear
    "    ", // z12 well x5..6, rail x7
    "    ", // z13 lane to the corridor door x9
    "    ", // z14
    "    ", // z15
    "    ", // z16 lane to the bath door x7 z17
  ]);
  // second layer y20: the shelf tops and a flower pot on the barrel
  const upper = {
    B: "bookshelf",
    f: "flower_pot",
  };
  layers(g, [5, 20, 7], upper, [
    "BB  ", // z7
    "f  B", // z8
    "   B", // z9
    "   B", // z10
  ]);
  // hanging lanterns under the loft floor (y23): one over the shelves, one over the stair well's east edge
  const lamps = { l: ["lantern", { hanging: "true" }] };
  layers(g, [5, 22, 7], lamps, [
    "    ", // z7
    " l  ", // z8 (x6)
    "    ", // z9
    "    ", // z10
    "    ", // z11
    "    ", // z12
    "    ", // z13
    "  l ", // z14 (x7)
    "    ", // z15
    "    ", // z16
  ]);
}
// SPDX-License-Identifier: AGPL-3.0-or-later
// Room: Loft. Open-truss storage loft under the main roof: a lit smoker focal piece on the north wall (the cured-meat
// bay), sacks of hay on the west wall, a worktable with a stool, barrels for stores on the east side, and lanterns
// standing on the barrels and sacks as the light. The hatch (16, 23, 20) is in the floor below the box; the lane from it
// (x 15..16) is kept clear. Drawn as text with layers(): rows along +x (x 7..16), successive rows along +z (z 8..21).
import { B, layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const ORIGIN_X = 7;
const ORIGIN_Z = 8;
const LOFT_FLOOR_Y = 24;

const FLOOR_LEGEND = {
  "b": ["barrel", { facing: "up" }],
  "S": ["smoker", { facing: "south", lit: "true" }],
  "h": ["hay_block", { axis: "y" }],
  "f": "spruce_fence",
  "i": ["spruce_stairs", { facing: "east", half: "bottom" }],
  "r": "red_carpet",
};

const TOP_LEGEND = {
  "L": ["lantern", { hanging: "false" }],
  "t": ["spruce_slab", { type: "bottom" }],
};

// y 24: the floor layer. Columns x 7..16, rows z 8..21.
const FLOOR_ROWS = [
  "..bbSbb...", // z 8  north wall: barrels either side of the smoker focal
  "..........", // z 9  open, in front of the focal
  "h.rrrr....", // z 10 hay sacks on the west wall, rug in front of the focal
  "h.rrrr....", // z 11
  "h...fi....", // z 12 worktable (fence) and its stool (stairs facing east)
  "..........", // z 13
  "..........", // z 14
  "..........", // z 15
  "..........", // z 16
  ".....bb...", // z 17 stores against the east side (x 12..13)
  ".....bb...", // z 18
  "..b.......", // z 19 one barrel south-west of the stores
  "..........", // z 20 clear: the hatch lane at x 15..16
  "..........", // z 21 clear: the ladder side
];

// y 25: the top layer (lanterns standing on barrels and sacks, the table top).
const TOP_ROWS = [
  "..L...L...", // z 8  lanterns on the focal barrels
  "..........", // z 9
  "..........", // z 10
  "L.........", // z 11 lantern on the hay sack
  "....t.....", // z 12 table top slab over the fence
  "..........", // z 13
  "..........", // z 14
  "..........", // z 15
  "..........", // z 16
  ".....L....", // z 17 lantern on the store barrel
  "..........", // z 18
  "..L.......", // z 19 lantern on the south-west barrel
  "..........", // z 20
  "..........", // z 21
];

/** Furniture and lights for the loft (the box x 7..16, y 24..27, z 8..21). */
export function build(g) {
  layers(g, [ORIGIN_X, LOFT_FLOOR_Y, ORIGIN_Z], { ...FLOOR_LEGEND, ...TOP_LEGEND }, [FLOOR_ROWS, TOP_ROWS]);
  // standing lanterns on the floor for the dim east edge (the room light map: 6..7 at x 15..16, z 11..14)
  g.set(16, LOFT_FLOOR_Y, 13, ...B.lantern(false));
  g.set(14, LOFT_FLOOR_Y, 17, ...B.lantern(false));
}

