const [x0, y0, z0, x1, y1, z1] = n.map(Number);
const g = load(file);
const short = (b) => b.replace("minecraft:", "");
for (let y = y1; y >= y0; y--) {
  console.log(`y=${y}`);
  for (let z = z0; z <= z1; z++) {
    const row = [];
