mkdir -p /tmp/mcd-scratch && cat > /tmp/mcd-scratch/lamps.mjs <<'EOF'
// Read-only planner: greedy lantern-post placement over the light tool's own y5/y6 maps.
// Usage: node lamps.mjs <build.nbt> <target level 1-15> <mcd path>
import { execFileSync } from "node:child_process";
import { load } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const [file, targetArg, mcd] = process.argv.slice(2);
const TARGET = Number(targetArg);
const LAMP_Y = 9;                       // lantern on a 3-high post standing at y 6
const g = load(file);
const AIR = /(^|:)(cave_)?air$/;
const bad = new Set(["minecraft:dirt_path", "minecraft:farmland", "minecraft:water"]);

// parse the light tool's maps: level per (x, z) at the stand row y, '#' = no floor
function readMap(y) {
  const out = execFileSync("node", [mcd, "light", file, "--y", String(y)], { encoding: "utf8" });
  const cells = new Map();
  for (const line of out.split("\n")) {
    const m = line.match(/^z\s*(\d+)\s+(\S+)\s*$/);
    if (!m) continue;
    const z = Number(m[1]);
    [...m[2]].forEach((ch, x) => {
      if (ch !== "#") cells.set(`${x},${z}`, parseInt(ch, 16));
    });
  }
  return cells;
}
const maps = { 5: readMap(5), 6: readMap(6) };
// current level of every floor cell and its stand row
const need = [];
for (const y of [5, 6]) for (const [k, v] of maps[y]) if (v < TARGET) {
  const [x, z] = k.split(",").map(Number);
  need.push({ x, z, s: y, v, covered: false });
}
// candidate posts: a free cell on the y6 layer with a solid block under it
const cands = [];
for (const [k] of maps[6]) {
  const [x, z] = k.split(",").map(Number);
  if (!AIR.test(g.blockAt(x, 6, z))) continue;
  const under = g.blockAt(x, 5, z);
  if (AIR.test(under) || bad.has(under)) continue;
  cands.push({ x, z });
}
// level a post at (cx, cz) gives a need cell: 15 - manhattan distance from the lantern (x, LAMP_Y, z)
const lvl = (c, n) => 15 - (Math.abs(c.x - n.x) + Math.abs(c.z - n.z) + (LAMP_Y - n.s));
const chosen = [];
let open = need.map((n) => ({ ...n, best: n.v }));
while (open.some((n) => n.best < TARGET) && cands.length) {
  let bestC = null, bestGain = 0;
  for (const c of cands) {
    if (chosen.some((p) => p.x === c.x && p.z === c.z)) continue;
    let gain = 0;
    for (const n of open) if (n.best < TARGET && lvl(c, n) > n.best) gain += Math.min(lvl(c, n), TARGET) - n.best;
    if (gain > bestGain) { bestGain = gain; bestC = c; }
  }
  if (!bestC) break;
  chosen.push(bestC);
  for (const n of open) n.best = Math.max(n.best, lvl(bestC, n));
}
const left = open.filter((n) => n.best < TARGET);
console.log(JSON.stringify({ target: TARGET, posts: chosen.length, uncovered: left.length, chosen }));
